package ru.neverland.townyenvironment;
import java.util.*;import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.townyenvironment.model.*;import ru.neverland.townyenvironment.config.*;
public final class EnvironmentForecastSmoke {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[] args)throws Exception{var y=new YamlConfiguration();try(var in=EnvironmentForecastSmoke.class.getResourceAsStream("/config.yml")){y.load(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8));}var settings=EnvironmentSettings.load(y);var state=new EnvironmentState(50,7,false);Map<String,Integer> active=Map.of("foundry",1);var f=EnvironmentForecast.calculate(state,active,settings,"foundry",5,3600,0);check((double)f.get("projected")>(double)f.get("baseline"),"upgrade affects actual pressure");var g=EnvironmentForecast.calculate(state,active,settings,"park",5,3600,0);check((double)g.get("projected")<(double)g.get("baseline"),"green alternative");check(state.pollution()==50&&state.cycles()==7&&active.equals(Map.of("foundry",1)),"what-if never mutates simulation");check(!(boolean)EnvironmentForecast.calculate(state,active,settings,"unknown",1,3600,0).get("relevant"),"unknown profile no invented effect");check((double)f.get("projected")<=100&&(double)g.get("projected")>=0,"physical range");System.out.println("EnvironmentForecastSmoke PASS: real profiles, upgrades, mitigation, clamping and immutable simulation");}
}
